script:
(function () {
  'use strict';
  // Federal income tax withholding for one paycheck, IRS Publication 15-T (2026), Worksheet 1A
  // (percentage method for automated payroll systems), plus FICA, a flat state rate and deductions.
  //   1a taxable wages = gross - pre-tax 401(k) - cafeteria-plan deductions; 1c = 1a x pay periods
  //   2020+ Form W-4: 1i = max(0, 1c + Step 4(a) - Step 4(b) - (Step 2 box ? 0 : $12,900 MFJ / $8,600))
  //   2019- Form W-4: 1l = max(0, 1c - allowances x $4,300)
  //   2g = C + D x (1i - A) from the Annual Percentage Method row (STANDARD or Step 2 CHECKBOX table)
  //   2h = 2g / periods; 3c = max(0, 2h - Step 3 / periods); 4b = 3c + Step 4(c)
  //   Social Security 6.2% up to the wage base after year-to-date pay; Medicare 1.45%, plus 0.9%
  //   on wages above $200,000 in the year (employer withholding rule). 401(k) stays FICA-taxable.
  // Checked in Node (b8pay/tests/w4.test.js):
  //   Pub. 15-T (2026) example: weekly $300 + $226.90 nonresident-alien add-on = $526.90, 2019 Form
  //   W-4, Single, 1 allowance -> 27,398.80 - 4,300 = 23,098.80; 1,240 + 12% x 3,198.80 = 1,623.86;
  //   / 52 = $31.23, which rounds to the $31 in the publication.
  //   Pub. 15-T (2026) biweekly wage bracket table, row $1,985-$2,005 (computed at its $1,995
  //   midpoint): MFJ $76, HOH $114, HOH Step 2 $200, Single $156, Single Step 2 $269 - all match.
  //   Biweekly $2,000 single, no adjustments: 52,000 - 8,600 = 43,400 -> 4,060 / 26 = $156.15.
  //   Step 3 $2,200 biweekly removes $84.62 a check; Step 4(c) adds dollar for dollar.
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Withholding tables: IRS Publication 15-T (2026), "2026 Percentage Method Tables for Automated
  //   Payroll Systems", Annual tables, rows [A at least, C tentative amount, D rate].
  //   Worksheet 1A lines 1g ($12,900 MFJ / $8,600 otherwise) and 1k ($4,300 per allowance).
  // Social Security wage base $184,500 and rates: SSA 2026 COLA fact sheet. Medicare and the
  //   0.9% Additional Medicare Tax withheld above $200,000: IRC 3101(b), 3102(f).
  var TAX_YEAR = 2026;
  var STANDARD = {
    mfj: [[0, 0, 0], [19300, 0, 0.10], [44100, 2480, 0.12], [120100, 11600, 0.22], [230700, 35932, 0.24],
          [422850, 82048, 0.32], [531750, 116896, 0.35], [788000, 206583.50, 0.37]],
    single: [[0, 0, 0], [7500, 0, 0.10], [19900, 1240, 0.12], [57900, 5800, 0.22], [113200, 17966, 0.24],
             [209275, 41024, 0.32], [263725, 58448, 0.35], [648100, 192979.25, 0.37]],
    hoh: [[0, 0, 0], [15550, 0, 0.10], [33250, 1770, 0.12], [83000, 7740, 0.22], [121250, 16155, 0.24],
          [217300, 39207, 0.32], [271750, 56631, 0.35], [656150, 191171, 0.37]]
  };
  var CHECKBOX = {
    mfj: [[0, 0, 0], [16100, 0, 0.10], [28500, 1240, 0.12], [66500, 5800, 0.22], [121800, 17966, 0.24],
          [217875, 41024, 0.32], [272325, 58448, 0.35], [400450, 103291.75, 0.37]],
    single: [[0, 0, 0], [8050, 0, 0.10], [14250, 620, 0.12], [33250, 2900, 0.22], [60900, 8983, 0.24],
             [108938, 20512, 0.32], [136163, 29224, 0.35], [328350, 96489.63, 0.37]],
    hoh: [[0, 0, 0], [12075, 0, 0.10], [20925, 885, 0.12], [45800, 3870, 0.22], [64925, 8077.50, 0.24],
          [112950, 19603.50, 0.32], [140175, 28315.50, 0.35], [332375, 95585.50, 0.37]]
  };
  var LINE_1G = { mfj: 12900, single: 8600, hoh: 8600 };
  var ALLOWANCE_VALUE = 4300;
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_START = 200000;
  // ---------------------------------------------------------------------------------------

  // --- calc start
  function tableRow(table, amount) {
    var row = table[0];
    for (var i = 0; i < table.length; i++) if (amount >= table[i][0]) row = table[i];
    return row;
  }

  // o: wages (line 1a), periods, form ('new' | 'old'), status, step2, step3, step4a, step4b,
  //    step4c, oldStatus ('single' | 'mfj' | 'higher'), allowances, exempt
  function worksheet(o) {
    var L = { '1a': o.wages, '1b': o.periods };
    L['1c'] = L['1a'] * L['1b'];
    var tableStatus, table, adjusted;
    if (o.form === 'old') {
      tableStatus = o.oldStatus === 'mfj' ? 'mfj' : 'single';
      table = STANDARD[tableStatus];
      L['1j'] = o.allowances;
      L['1k'] = o.allowances * ALLOWANCE_VALUE;
      L['1l'] = Math.max(0, L['1c'] - L['1k']);
      adjusted = L['1l'];
    } else {
      tableStatus = o.status;
      table = o.step2 ? CHECKBOX[tableStatus] : STANDARD[tableStatus];
      L['1d'] = o.step4a;
      L['1e'] = L['1c'] + L['1d'];
      L['1f'] = o.step4b;
      L['1g'] = o.step2 ? 0 : LINE_1G[tableStatus];
      L['1h'] = L['1f'] + L['1g'];
      L['1i'] = Math.max(0, L['1e'] - L['1h']);
      adjusted = L['1i'];
    }
    var row = tableRow(table, adjusted);
    L['2a'] = adjusted; L['2b'] = row[0]; L['2c'] = row[1]; L['2d'] = row[2];
    L['2e'] = L['2a'] - L['2b'];
    L['2f'] = L['2e'] * L['2d'];
    L['2g'] = L['2c'] + L['2f'];
    L['2h'] = L['2g'] / L['1b'];
    L['3a'] = o.form === 'old' ? 0 : o.step3;
    L['3b'] = L['3a'] / L['1b'];
    L['3c'] = Math.max(0, L['2h'] - L['3b']);
    L['4a'] = o.step4c;
    L['4b'] = L['3c'] + L['4a'];
    var withheld = o.exempt ? 0 : L['4b'];
    return { L: L, withheld: withheld, tableStatus: tableStatus, checkbox: o.form !== 'old' && o.step2, rate: row[2] };
  }

  function fica(ficaWages, ytd) {
    var ssRoom = Math.max(0, SS_WAGE_BASE - ytd);
    var ss = SS_RATE * Math.min(ficaWages, ssRoom);
    var over = Math.max(0, ytd + ficaWages - Math.max(ADDL_MEDICARE_START, ytd));
    var medicare = MEDICARE_RATE * ficaWages + ADDL_MEDICARE_RATE * over;
    return { ss: ss, medicare: medicare };
  }

  // p: gross, k401Pct, pretax, post, stateRate, ytd + worksheet inputs (per paycheck amounts)
  function paycheck(p) {
    var k401 = p.gross * p.k401Pct / 100;
    var pretax = Math.min(p.pretax, Math.max(0, p.gross - k401));
    var wages = Math.max(0, p.gross - k401 - pretax);
    var ws = worksheet({
      wages: wages, periods: p.periods, form: p.form, status: p.status, step2: p.step2, step3: p.step3,
      step4a: p.step4a, step4b: p.step4b, step4c: p.step4c, oldStatus: p.oldStatus,
      allowances: p.allowances, exempt: p.exempt
    });
    var f = fica(Math.max(0, p.gross - pretax), p.ytd);
    var state = p.stateRate / 100 * wages;
    var net = p.gross - k401 - pretax - ws.withheld - f.ss - f.medicare - state - p.post;
    return { k401: k401, pretax: pretax, wages: wages, ws: ws, fed: ws.withheld, ss: f.ss,
             medicare: f.medicare, state: state, post: p.post, net: net };
  }
  // --- calc end

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var STATUS_NAME = { single: 'Single or married filing separately', mfj: 'Married filing jointly', hoh: 'Head of household' };

  function el(id) { return document.getElementById(id); }
  function num(id) { var v = parseFloat(el(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { var e = el(id); if (e) e.textContent = text; }
  function fmt(v) { return Math.abs(v) < 0.005 ? money.format(0) : money.format(v); }
  function neg(v) { return Math.abs(v) < 0.005 ? money.format(0) : '−' + money.format(v); }
  function addRow(tbody, cells, strong) {
    var tr = document.createElement('tr');
    cells.forEach(function (text, i) {
      var c = document.createElement(i === 0 ? 'th' : 'td');
      if (i === 0) c.setAttribute('scope', 'row');
      if (strong) { var s = document.createElement('strong'); s.textContent = text; c.appendChild(s); }
      else c.textContent = text;
      tr.appendChild(c);
    });
    tbody.appendChild(tr);
  }
  function clearBody(id) { var b = el(id); while (b.firstChild) b.removeChild(b.firstChild); return b; }

  function update() {
    var form4 = el('wxForm4').value === 'old' ? 'old' : 'new';
    el('wxNewGroup').hidden = form4 === 'old';
    el('wxOldGroup').hidden = form4 !== 'old';
    var p = {
      gross: num('wxGross'), periods: parseInt(el('wxFreq').value, 10), form: form4,
      status: el('wxStatus').value, step2: el('wxStep2').checked, step3: num('wxStep3'),
      step4a: num('wxStep4a'), step4b: num('wxStep4b'), step4c: num('wxStep4c'),
      oldStatus: el('wxOldStatus').value, allowances: Math.round(num('wxAllowances')),
      k401Pct: num('wx401k'), pretax: num('wxPretax'), stateRate: num('wxState'),
      post: num('wxPost'), ytd: num('wxYtd'), exempt: el('wxExempt').checked
    };
    if (!STANDARD[p.status]) p.status = 'single';
    if (!(p.periods > 0)) p.periods = 26;
    var vals = [p.gross, p.step3, p.step4a, p.step4b, p.step4c, p.k401Pct, p.pretax, p.stateRate, p.post, p.ytd];
    if (form4 === 'old') vals.push(p.allowances);
    var error = el('wxError');
    var bad = vals.some(function (v) { return !isFinite(v) || v < 0 || v > 1e9; }) ||
              p.k401Pct > 100 || p.stateRate > 20 || (form4 === 'old' && p.allowances > 99);
    var msg = 'Enter amounts of $0 or more, a 401(k) rate from 0 to 100%, a state rate from 0 to 20% and 0 to 99 allowances.';
    if (!bad && p.gross * p.k401Pct / 100 + p.pretax + p.post > p.gross + 0.005) {
      bad = true;
      msg = 'Your deductions add up to more than this paycheck. Lower the 401(k) rate or the per-check deductions.';
    }
    error.hidden = !bad;
    if (bad) { error.textContent = msg; return; }

    var r = paycheck(p), L = r.ws.L, n = p.periods;
    set('wxNet', money.format(r.net));
    set('wxFed', money.format(r.fed));
    set('wxFedYear', money.format(r.fed * n));
    set('wxAdjusted', money.format(L['2a']));
    set('wxTable', (r.ws.checkbox ? 'Step 2 checkbox' : 'Standard') + ', ' +
        (form4 === 'old' ? (r.ws.tableStatus === 'mfj' ? 'Married filing jointly' : 'Single') : STATUS_NAME[r.ws.tableStatus]));
    set('wxMarginal', p.exempt ? '0%' : Math.round(r.ws.rate * 100) + '%');
    set('wxRounded', money.format(Math.round(r.fed)));

    var sheet = clearBody('wxSheet');
    var lines;
    if (form4 === 'old') {
      lines = [['1a', 'Taxable wages this pay period', fmt(L['1a'])], ['1b', 'Pay periods per year', String(n)],
        ['1c', 'Annual wages (1a × 1b)', fmt(L['1c'])], ['1j', 'Allowances on your 2019 or earlier Form W-4', String(L['1j'])],
        ['1k', 'Allowances × ' + whole.format(ALLOWANCE_VALUE), fmt(L['1k'])],
        ['1l', 'Adjusted annual wage amount (1c − 1k, not below zero)', fmt(L['1l'])]];
    } else {
      lines = [['1a', 'Taxable wages this pay period', fmt(L['1a'])], ['1b', 'Pay periods per year', String(n)],
        ['1c', 'Annual wages (1a × 1b)', fmt(L['1c'])], ['1d', 'Step 4(a) other income', fmt(L['1d'])],
        ['1e', '1c + 1d', fmt(L['1e'])], ['1f', 'Step 4(b) deductions', fmt(L['1f'])],
        ['1g', p.step2 ? 'Step 2 box checked, so zero' : 'Standard allowance built into the table', fmt(L['1g'])],
        ['1h', '1f + 1g', fmt(L['1h'])], ['1i', 'Adjusted annual wage amount (1e − 1h, not below zero)', fmt(L['1i'])]];
    }
    lines = lines.concat([
      ['2b', 'Column A: start of your row in the annual table', fmt(L['2b'])],
      ['2c', 'Column C: tentative amount for that row', fmt(L['2c'])],
      ['2d', 'Column D: rate for that row', Math.round(L['2d'] * 100) + '%'],
      ['2e', 'Adjusted wages above column A (2a − 2b)', fmt(L['2e'])],
      ['2f', '2e × 2d', fmt(L['2f'])], ['2g', 'Annual tentative withholding (2c + 2f)', fmt(L['2g'])],
      ['2h', 'Tentative withholding per paycheck (2g ÷ 1b)', fmt(L['2h'])],
      ['3a', form4 === 'old' ? 'Step 3 credits (not on older forms)' : 'Step 3 credits for the year', fmt(L['3a'])],
      ['3b', 'Credits per paycheck (3a ÷ 1b)', fmt(L['3b'])],
      ['3c', 'Withholding after credits (2h − 3b, not below zero)', fmt(L['3c'])],
      ['4a', 'Extra withholding you asked for', fmt(L['4a'])],
      ['4b', 'Federal income tax to withhold (3c + 4a)', fmt(L['4b'])]
    ]);
    lines.forEach(function (line) { addRow(sheet, line, line[0] === '4b'); });

    var bd = clearBody('wxBreakdown');
    [['Gross pay', fmt(p.gross), fmt(p.gross * n)],
     ['401(k) / 403(b) contribution', neg(r.k401), neg(r.k401 * n)],
     ['Health and other pre-tax deductions', neg(r.pretax), neg(r.pretax * n)],
     ['Federal income tax withheld', neg(r.fed), neg(r.fed * n)],
     ['Social Security (6.2%)', neg(r.ss), neg(r.ss * n)],
     ['Medicare (1.45%, plus 0.9% above $200,000)', neg(r.medicare), neg(r.medicare * n)],
     ['State and local income tax', neg(r.state), neg(r.state * n)],
     ['After-tax deductions', neg(r.post), neg(r.post * n)]].forEach(function (row) { addRow(bd, row); });
    addRow(bd, ['Take-home pay', money.format(r.net), money.format(r.net * n)], true);

    var notes = [];
    if (p.exempt) notes.push('With exemption claimed, no federal income tax is withheld. Social Security and Medicare still apply. An exemption lasts only for the calendar year, so you need a new Form W-4 by February 15 of next year to keep it.');
    if (!p.exempt && L['3b'] > L['2h'] + 0.005) notes.push('Your Step 3 credits are larger than the tentative withholding, so withholding is zero apart from any extra amount you asked for.');
    if (form4 === 'old' && p.oldStatus === 'higher') notes.push('"Married, but withhold at higher Single rate" uses the Single table.');
    if (p.ytd + Math.max(0, p.gross - r.pretax) > SS_WAGE_BASE) notes.push('Your pay for the year passes the ' + TAX_YEAR + ' Social Security wage base of ' + whole.format(SS_WAGE_BASE) + ', so Social Security tax stops there.');
    if (p.ytd > 0) notes.push('The full-year column simply multiplies this paycheck by your pay periods.');
    var noteEl = el('wxNote');
    noteEl.hidden = notes.length === 0;
    noteEl.textContent = notes.join(' ');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('wxForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
